import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { chromium } from 'playwright-core';

// Uses only the ephemeral accounts/records generated by the PHP browser fixture.
// The mixed-branch ticket is deliberately NOT a permitted production transition.
const base = 'http://127.0.0.1:8742';
const fixturePath = process.env.PICKUP_FIXTURE;
assert(fixturePath, 'PICKUP_FIXTURE must point to the private disposable fixture.');
const fixture = JSON.parse(readFileSync(fixturePath, 'utf8'));
assert(fixture.ownership, 'Run tests/ownership-browser-fixture.php first.');
const owner = fixture.ownership;
const browser = await chromium.launch({
  executablePath: process.env.CHROME_PATH,
  channel: process.env.CHROME_PATH ? undefined : 'chrome',
});

async function signIn(email, width = 390, javaScriptEnabled = true) {
  const context = await browser.newContext({
    viewport: { width, height: 900 },
    javaScriptEnabled,
  });
  await context.route('**/*', (route) =>
    route.request().url().startsWith(base + '/') ? route.continue() : route.abort()
  );
  const page = await context.newPage();
  page.setDefaultTimeout(12000);
  await page.goto(base + '/admin/login.php');
  await page.locator('#email').fill(email);
  await page.locator('#password').fill(fixture.password);
  await page.getByRole('button', { name: 'Login', exact: true }).click();
  await page.waitForURL(/\/(dashboard|staff_home)\.php/);
  return { page, context };
}

async function openDevice(page, id, status = 200) {
  const response = await page.goto(base + '/admin/device.php?id=' + id);
  assert.equal(response.status(), status, 'Device request returned unexpected status.');
  return page;
}

async function noHorizontalOverflow(page) {
  const widths = await page.evaluate(() => ({
    content: document.documentElement.scrollWidth,
    viewport: document.documentElement.clientWidth,
  }));
  assert(widths.content <= widths.viewport + 1,
    'Ownership device detail overflows at ' + widths.viewport + 'px: ' +
    widths.content + 'px');
}

async function branchText(page, label) {
  const heading = page.locator('dt').filter({ hasText: label });
  assert.equal(await heading.count(), 1, 'Ownership label missing or duplicated: ' + label);
  return (await heading.locator('..').locator('dd').innerText()).trim();
}

async function noOwnershipLabels(page, role) {
  assert.equal(await page.getByText('Repair branch (read-only)', { exact: true }).count(), 0,
    role + ' received private diagnostic ownership labels.');
  assert.equal(await page.getByText('Ticket / billing branch (read-only)', { exact: true }).count(), 0,
    role + ' received ticket financial branch diagnostics.');
}

try {
  const manager = await signIn(fixture.manager);
  await openDevice(manager.page, owner.local_device);
  assert.equal(await branchText(manager.page, 'Repair branch (read-only)'), owner.source_label);
  assert.equal(await branchText(manager.page, 'Ticket / billing branch (read-only)'), owner.source_label);
  assert.equal(await manager.page.getByText('Branch assignment needs staff review.', { exact: false }).count(), 0,
    'Aligned ownership incorrectly triggered a mismatch warning.');

  for (const width of [320, 390, 768, 1440]) {
    await manager.page.setViewportSize({ width, height: 900 });
    await openDevice(manager.page, owner.remote_device);
    assert.equal(await branchText(manager.page, 'Repair branch (read-only)'), owner.remote_label);
    assert.equal(await branchText(manager.page, 'Ticket / billing branch (read-only)'), owner.source_label);
    assert.equal(await manager.page.getByText('Branch assignment needs staff review.', { exact: false }).count(), 1,
      'Missing review warning on intentionally divergent ownership at ' + width + 'px');
    assert.equal(await manager.page.locator('em[data-rt-ownership]').count(), 0,
      'Untrusted branch label rendered as HTML instead of escaped text.');
    await noHorizontalOverflow(manager.page);
  }
  const sourceCash = await manager.page.goto(base + '/admin/cash.php?ticket_id=' + owner.ticket_id);
  assert.equal(sourceCash.status(), 200,
    'Ticket origin manager lost ticket-level billing access during diagnostics.');
  await manager.context.close();

  const admin = await signIn(fixture.admin, 390);
  await openDevice(admin.page, owner.remote_device);
  assert.equal(await branchText(admin.page, 'Repair branch (read-only)'), owner.remote_label);
  await noHorizontalOverflow(admin.page);
  await admin.context.close();

  const noJs = await signIn(fixture.manager, 390, false);
  await openDevice(noJs.page, owner.remote_device);
  assert.equal(await branchText(noJs.page, 'Repair branch (read-only)'), owner.remote_label,
    'Ownership diagnostics require JavaScript.');
  await noJs.context.close();

  const tech = await signIn(fixture.technician);
  await openDevice(tech.page, owner.local_device);
  await noOwnershipLabels(tech.page, 'Technician');
  await openDevice(tech.page, owner.remote_device, 404);
  await tech.context.close();

  for (const [role, email] of [
    ['Intake agent', fixture.intake_agent], ['Viewer', fixture.viewer],
  ]) {
    const actor = await signIn(email);
    await openDevice(actor.page, owner.remote_device);
    await noOwnershipLabels(actor.page, role);
    await actor.context.close();
  }

  for (const [role, email] of [
    ['Destination manager', owner.remote_manager],
    ['Destination technician', owner.remote_technician],
  ]) {
    const actor = await signIn(email);
    await openDevice(actor.page, owner.remote_device, 404);
    assert(!(await actor.page.locator('body').innerText()).includes(owner.remote_label),
      role + ' obtained a repair branch label outside ticket-level scope.');
    await openDevice(actor.page, owner.local_device, 404);
    if (role === 'Destination manager') {
      const bill = await actor.page.goto(base + '/admin/cash.php?ticket_id=' + owner.ticket_id);
      assert.equal(bill.status(), 404,
        'Receiving manager accessed origin ticket cash authorization by repair location.');
    }
    await actor.context.close();
  }

  for (const [role, email] of [
    ['Origin cashier', fixture.cashier],
    ['Destination cashier', owner.remote_cashier],
    ['Courier', fixture.courier],
  ]) {
    const actor = await signIn(email);
    await openDevice(actor.page, owner.remote_device, 403);
    await actor.context.close();
  }

  console.log('PASS: authenticated ownership display across 320/390/768/1440px; escaped labels; no-JS; origin cash and role/sibling denials.');
} finally {
  await browser.close();
}
